while read -r file;do file2=$(echo "$file" | sed "s/\.txt/_unaLinea\.txt/g" );awk '/^[0-9]{2}\/[0-9]{2}\/[0-9]{4}/ {collecting=1; buffer=$0; next} /https:\/\/www\.boe\.es\/buscar\/doc\.php/ {if(collecting){gsub(/[ \t]+/, " ", buffer); print buffer; collecting=0} print $0; next} /PDF: https:\/\// {print $0; next} collecting {buffer=buffer " " $0}' ${file} >${file2};done < <( ls 2026-11-14-08-5*.txt );
